mapper.select:
SELECT COUNT(*)
FROM organization_user_mappings actor_mapping
JOIN organization_user_mappings target_mapping
    ON target_mapping.organization_code = actor_mapping.organization_code
WHERE actor_mapping.user_id = #{actorUserId}
  AND actor_mapping.status = 'ACTIVE'
  AND target_mapping.user_id = #{targetUserId}
  AND target_mapping.organization_code = #{organizationCode}
  AND target_mapping.status = 'ACTIVE'

SELECT COUNT(*)
FROM input_period_settings
WHERE evaluation_year = #{evaluationYear}
  AND active_yn = 'Y'
  AND (area_code IS NULL OR area_code = #{areaCode})
  AND (organization_code IS NULL OR organization_code = #{organizationCode})
  AND start_at <= #{checkedAt}
  AND end_at >= #{checkedAt}

SELECT COUNT(*)
FROM evaluation_date_settings
WHERE evaluation_year = #{evaluationYear}
  AND active_yn = 'Y'
  AND (area_code IS NULL OR area_code = #{areaCode})
  AND (organization_code IS NULL OR organization_code = #{organizationCode})
  AND start_at::date <= #{occurredDate}
  AND end_at::date >= #{occurredDate}

SELECT COUNT(*)
FROM evaluation_finalizations
WHERE target_user_id = #{targetUserId}
  AND evaluation_year = #{evaluationYear}
  AND final_status = 'EVALUATION_CONFIRMED'
